/* ━━━ Mock analytics generator (per-room) ━━━ */
function genMockAnalytics(roomId) {
  const seed = String(roomId).split("").reduce((s,c) => s + c.charCodeAt(0), 0);
  const rand = (i) => { const x = Math.sin(seed + i) * 10000; return x - Math.floor(x); };
  const days = 220;
  const start = new Date("2024-09-15").getTime();
  const series = Array.from({length: days}).map((_,i) => {
    const t = start + i * 86400000;
    const base = i < 100 ? rand(i)*60 : i < 140 ? 0 : 30 + rand(i)*120;
    const views = Math.round(base);
    const clicks = Math.round(views * (0.18 + rand(i+99)*0.08));
    const apps = Math.round(clicks * (0.42 + rand(i+199)*0.1));
    return { x: t, views, clicks, apps };
  });
  const totalViews = series.reduce((s,d) => s+d.views, 0);
  const totalClicks = series.reduce((s,d) => s+d.clicks, 0);
  const totalApps = series.reduce((s,d) => s+d.apps, 0);
  return {
    totalViews, totalClicks, totalApps,
    ctr: totalViews ? (totalClicks/totalViews*100) : 0,
    conversionRate: totalClicks ? (totalApps/totalClicks*100) : 0,
    timeSeries: series,
    countries: [
      { code:"USA", name:"United States", count: 18 },
      { code:"GBR", name:"United Kingdom", count: 14 },
      { code:"DEU", name:"Germany", count: 12 },
      { code:"FRA", name:"France", count: 11 },
      { code:"ESP", name:"Spain", count: 10 },
      { code:"ITA", name:"Italy", count: 9 },
      { code:"NLD", name:"Netherlands", count: 8 },
      { code:"AUS", name:"Australia", count: 7 },
      { code:"CAN", name:"Canada", count: 5 },
      { code:"BRA", name:"Brazil", count: 4 },
      { code:"JPN", name:"Japan", count: 3 },
      { code:"MEX", name:"Mexico", count: 2 },
      { code:"NOR", name:"Norway", count: 2 },
      { code:"GRC", name:"Greece", count: 1 },
      { code:"PRT", name:"Portugal", count: 1 },
    ],
    gender: { Female: Math.round(totalApps*.68), Male: Math.round(totalApps*.27), "Non-Binary": Math.round(totalApps*.04), Other: Math.round(totalApps*.01) },
    experience: { "Entry Level": Math.round(totalApps*.62), "Intermediate": Math.round(totalApps*.28), "Advanced": Math.round(totalApps*.08), "Professional": Math.round(totalApps*.02) },
    education: { "High School": Math.round(totalApps*.12), "Some College": Math.round(totalApps*.08), "Associate": Math.round(totalApps*.04), "Bachelor's": Math.round(totalApps*.62), "Master's": Math.round(totalApps*.10), "Doctorate": Math.round(totalApps*.04) },
  };
}

