    setShowcases(p => [...p, { id, title: newSc.title, brand: newSc.brand, description: newSc.description, status: "draft", artistIds: newScSelected, date: new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }), favs: 0, declined: 0, pending: 0, shareId }]);
